var mx10004VRFUnitsAddedOIDNames = []string{}

var mx10004VRFUnitsRemovedOIDNames = []string{}

func restoreMx10004VRFUnits(t *testing.T, cur map[[2]string]string) {
	t.Helper()
	reverseProfileEdits(t, cur, juniperMx10004Profile, "juniper_mx10004 VRF units", mx10004VRFUnitsEdits)
}

func mx10004VRFUnitsOIDNamesBefore(t *testing.T, names []string) []string {
	t.Helper()
	return reverseOIDNameEdits(t, names, "juniper_mx10004 VRF units", mx10004VRFUnitsAddedOIDNames, mx10004VRFUnitsRemovedOIDNames)
}

func TestMx10004VRFUnitsReproduceTheParentCorpus(t *testing.T) {
	if got := corpusTagDigestAt(t, corpusValuesAt(t, mx10004VRFUnitsParentRevision), mx10004VRFUnitsParentRevision); got != shippedTagDigestBeforeMx10004VRFUnits {
		t.Errorf("reversing the VRF units change gives digest %s, want %s: another shipped row changed without being recorded",
			got, shippedTagDigestBeforeMx10004VRFUnits)
	}
}

func TestMx10004VRFUnitsRePinIsOnlyTheEdit(t *testing.T) {
	restored := restoreCorpusOIDNamesTo(t, collectShippedOIDs(t), mx10004VRFUnitsParentRevision)
	if got := corpusOIDNameDigest(restored); got != shippedOIDEncodingDigestBeforeMx10004VRFUnits {
		t.Errorf("reversing the VRF units OID names gives digest %s, want %s", got, shippedOIDEncodingDigestBeforeMx10004VRFUnits)
	}
}
